@immutable
class BrandTokens extends ThemeExtension<BrandTokens> {
  const BrandTokens({
    required this.success,
    required this.heroGradient,
    required this.gutter,
  });

  final Color success;
  final Gradient heroGradient;
  final double gutter;          // discrete — must not be interpolated

  static BrandTokens of(BuildContext context) =>
      Theme.of(context).extension<BrandTokens>()!;

  @override
  BrandTokens copyWith({Color? success, Gradient? heroGradient, double? gutter}) =>
      BrandTokens(
        success: success ?? this.success,
        heroGradient: heroGradient ?? this.heroGradient,
        gutter: gutter ?? this.gutter,
      );

  @override
  BrandTokens lerp(ThemeExtension<BrandTokens>? other, double t) {
    if (other is! BrandTokens) return this;   // never crash mid-transition
    return BrandTokens(
      success: Color.lerp(success, other.success, t)!,
      heroGradient: Gradient.lerp(heroGradient, other.heroGradient, t)!,
      gutter: t < 0.5 ? gutter : other.gutter,   // snap, do not tween
    );
  }

  static const light = BrandTokens(
    success: Color(0xFF1B873F),
    heroGradient: LinearGradient(colors: [Color(0xFF6750A4), Color(0xFF00695C)]),
    gutter: 16,
  );

  static const dark = BrandTokens(
    success: Color(0xFF5CD68A),
    heroGradient: LinearGradient(colors: [Color(0xFFD0BCFF), Color(0xFF4DB6AC)]),
    gutter: 16,
  );
}

