const _brandSeed = Color(0xFF6750A4);

class App extends StatelessWidget {
  const App({super.key});

  @override
  Widget build(BuildContext context) {
    return DynamicColorBuilder(
      // Non-null only on Android 12+. Null on older Android, iOS, web, desktop.
      builder: (ColorScheme? lightDynamic, ColorScheme? darkDynamic) {
        final light = lightDynamic?.harmonized() ??
            ColorScheme.fromSeed(seedColor: _brandSeed);
        final dark = darkDynamic?.harmonized() ??
            ColorScheme.fromSeed(seedColor: _brandSeed, brightness: Brightness.dark);

        return MaterialApp(
          theme: _themeFrom(light),
          darkTheme: _themeFrom(dark),
          home: const HomePage(),
        );
      },
    );
  }
}

ThemeData _themeFrom(ColorScheme scheme) => ThemeData(
      colorScheme: scheme,
      extensions: [
        // A semantic colour with no slot in ColorScheme. Rotate its hue toward
        // the wallpaper palette so it reads as part of the same system.
        StatusColors(
          success: const Color(0xFF2E7D32).harmonizeWith(scheme.primary),
        ),
      ],
    );

