// packages/acme_design/lib/src/theme/acme_theme.dart
abstract final class AcmeTheme {
  static ThemeData light() => _build(Brightness.light);
  static ThemeData dark() => _build(Brightness.dark);

  static ThemeData _build(Brightness brightness) {
    final scheme = ColorScheme.fromSeed(seedColor: _seed, brightness: brightness);
    return ThemeData(
      colorScheme: scheme,
      extensions: [AcmeTokens.forScheme(scheme)],
      filledButtonTheme: FilledButtonThemeData(style: _filledButtonStyle),
    );
  }
}

// Typed access — no app touches Theme.of(context).extension<T>() directly.
extension AcmeThemeX on BuildContext {
  AcmeTokens get acme => Theme.of(this).extension<AcmeTokens>()!;
}

