import 'dart:ui' show lerpDouble;
import 'package:flutter/material.dart';

// ── Theme-shaped and lerpable: ThemeExtension ──
@immutable
class AcmeTokens extends ThemeExtension<AcmeTokens> {
  const AcmeTokens({required this.success, required this.gutter});
  final Color success;
  final double gutter;

  @override
  AcmeTokens copyWith({Color? success, double? gutter}) =>
      AcmeTokens(success: success ?? this.success, gutter: gutter ?? this.gutter);

  @override
  AcmeTokens lerp(AcmeTokens? other, double t) {
    if (other == null) return this;
    return AcmeTokens(
      success: Color.lerp(success, other.success, t)!,
      gutter: lerpDouble(gutter, other.gutter, t)!,
    );
  }
}

// ── Its own lifetime and change rate: your own InheritedWidget ──
class NowPlayingAccent extends InheritedWidget {
  const NowPlayingAccent({super.key, required this.color, required super.child});

  final Color color; // changes per track, dozens of times per session

  static Color? maybeOf(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<NowPlayingAccent>()?.color;

  static Color of(BuildContext context) {
    final color = maybeOf(context);
    assert(color != null, 'No NowPlayingAccent above this widget — wrap the player route.');
    return color!;
  }

  @override
  bool updateShouldNotify(NowPlayingAccent old) => old.color != color;
}

