// packages/acme_lints/lib/acme_lints.dart
import 'package:analyzer/error/listener.dart';
import 'package:custom_lint_builder/custom_lint_builder.dart';

PluginBase createPlugin() => _AcmeLints();

class _AcmeLints extends PluginBase {
  @override
  List<LintRule> getLintRules(CustomLintConfigs configs) => [const NoRawColor()];
}

class NoRawColor extends DartLintRule {
  const NoRawColor() : super(code: _code);

  static const _code = LintCode(
    name: 'acme_no_raw_color',
    problemMessage: 'Use a ColorScheme role or an AcmeTokens colour, not a raw Color.',
  );

  @override
  void run(CustomLintResolver resolver, ErrorReporter reporter, CustomLintContext context) {
    // The design system itself is the one place allowed to write literals.
    if (resolver.path.contains('/packages/acme_design/')) return;

    context.registry.addInstanceCreationExpression((node) {
      if (node.staticType?.getDisplayString() == 'Color') {
        reporter.atNode(node, _code);
      }
    });
  }
}

